def compute(df, **params):
    period = int(params.get("period", 14))
    close = df["close"].tolist()

    result = [0.0] * len(close)

    if len(close) <= period:
        return result

    gains = []
    losses = []

    for i in range(1, len(close)):
        change = float(close[i]) - float(close[i - 1])
        gains.append(max(change, 0.0))
        losses.append(max(-change, 0.0))

    avg_gain = sum(gains[:period]) / period
    avg_loss = sum(losses[:period]) / period

    def calculate_rsi(gain, loss):
        if loss == 0:
            return 100.0 if gain > 0 else 50.0
        rs = gain / loss
        return 100.0 - (100.0 / (1.0 + rs))

    result[period] = calculate_rsi(avg_gain, avg_loss)

    for i in range(period + 1, len(close)):
        idx = i - 1

        avg_gain = (
            avg_gain * (period - 1) + gains[idx]
        ) / period

        avg_loss = (
            avg_loss * (period - 1) + losses[idx]
        ) / period

        result[i] = calculate_rsi(avg_gain, avg_loss)

    return result
